 g.strokeStyle=rock?'#5799db':'#f2c64d';g.lineWidth=12;g.lineCap='round';g.beginPath();g.moveTo(-19,-61);g.lineTo(-44,-77+Math.sin(a.life*12)*8);g.stroke();ellipse(-47,-77+Math.sin(a.life*12)*8,7,7,'#ffcd9b');
