const $=id=>document.getElementById(id),c=$('canvas'),g=c.getContext('2d');
const seasons=[['🌸 SPRING · 봄','#dff0df','#a3ca83','#e6efb0','🌸'],['☀️ SUMMER · 여름','#c9eef2','#6fbb79','#addb6c','☀️'],['🍁 AUTUMN · 가을','#f8e3c5','#c79860','#dfbf78','🍁'],['❄️ WINTER · 겨울','#e1edf4','#a3b7c3','#e9f2f5','❄️']];
let state='ready',elapsed=0,score=0,lives=2,boost=0,immune=0,spawn=1,items=[],particles=[],world=0,last=0,keys={},player={x:210,y:432,jump:0,vy:0},muted=false,audio=new Audio(),audioURL;
audio.src='soundtrack.m4a';audio.preload='metadata';audio.loop=true;audio.volume=.55;
const speedAt=t=>1+Math.floor(t/20)*.5;
function reset(){elapsed=score=boost=immune=world=0;lives=2;spawn=.8;attacker=null;items=[];particles=[];player={x:210,y:432,jump:0,vy:0};state='running';$('overlay').style.display='none';$('pause').textContent='Ⅱ 일시정지';if(audio.src){audio.currentTime=0;audio.play().catch(()=>{});}}
function end(win){state=win?'won':'lost';audio.pause();$('overlay').style.display='flex';$('title').textContent=win?'사계절 완주! 짱구의 대승리!':'아쉽다! 다시 달려 볼까요?';$('message').innerHTML=`${Math.floor(elapsed)}초 동안 달렸어요 · ${score.toLocaleString()}점<br>${win?'떡잎마을 최고의 러너가 되었어요!':'하트 부스터와 점프를 활용해 보세요.'}`;$('start').textContent='다시 도전하기 →';}
function pause(){if(!['running','paused'].includes(state))return;state=state==='running'?'paused':'running';$('pause').textContent=state==='paused'?'▶ 계속하기':'Ⅱ 일시정지';if(state==='paused')audio.pause();else if(audio.src)audio.play().catch(()=>{});}
$('start').onclick=reset;$('pause').onclick=pause;
$('sound').onclick=()=>{muted=!muted;audio.muted=muted;$('sound').textContent=muted?'♫ 소리 꺼짐':'♫ 소리 켜짐';};
$('music').onchange=e=>{const file=e.target.files[0];if(!file)return;audio.pause();if(audioURL)URL.revokeObjectURL(audioURL);audioURL=URL.createObjectURL(file);audio.src=audioURL;$('musicStatus').textContent=file.name;if(state==='running')audio.play().catch(()=>{$('musicStatus').textContent='재생할 수 없는 파일입니다. 다른 음원을 선택하세요.';});};
function key(k,down){keys[k]=down;if(down&&k===' '&&state==='running'&&player.jump===0){player.vy=650;} }
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','w','a','s','d','arrowup','arrowdown'].includes(k)){e.preventDefault();key(k,true);}if(k==='escape')pause();});addEventListener('keyup',e=>key(e.key.toLowerCase(),false));addEventListener('blur',()=>{keys={};if(state==='running')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='running')pause();});
document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);key(b.dataset.key,true);};b.onpointerup=b.onpointercancel=()=>key(b.dataset.key,false);});
function addItem(){const danger=Math.random()<.46;const type=danger?['rock','snot','doll'][Math.floor(Math.random()*3)]:['star','candy','cookie','heart'][Math.random()<.12?3:Math.floor(Math.random()*3)];let y=danger?(340+Math.random()*110):325+Math.random()*130;items.push({x:danger?1120:1300,y,type,danger,passed:false});if(danger)attacker={type,life:1.4,y};}
function update(dt){elapsed=Math.min(300,elapsed+dt);if(attacker)attacker.life-=dt;const sp=speedAt(elapsed);boost=Math.max(0,boost-dt);immune=Math.max(0,immune-dt);world+=dt*180*sp*(boost>0?1.35:1);player.x=Math.max(65,Math.min(650,player.x+((keys.d?1:0)-(keys.a?1:0))*310*dt));player.y=Math.max(335,Math.min(495,player.y+((keys.s?1:0)-(keys.w?1:0))*240*dt));if(player.jump>0||player.vy>0){player.jump+=player.vy*dt;player.vy-=1550*dt;if(player.jump<=0){player.jump=0;player.vy=0;}}
spawn-=dt;if(spawn<=0){addItem();spawn=(.85+Math.random()*.7)/Math.sqrt(sp);}for(const it of items){it.x-=dt*(180*sp*(boost>0?1.35:1)+(it.type==='rock'?80:it.type==='snot'?40:it.type==='doll'?60:0));const size=boost>0?2:1;const hit=Math.abs(it.x-player.x)<(it.danger?24:23)+19*size&&Math.abs(it.y-(player.y-player.jump-30*size))<25+26*size;if(hit&&!it.passed){it.passed=true;if(it.danger){if(boost<=0&&immune<=0){lives--;immune=3;particles.push({text:lives?'한 번 더! 부활 ✨':'앗!',life:2,x:player.x,y:player.y-100});if(lives===0){end(false);return;}}}else{score+=it.type==='star'?100:it.type==='heart'?50:150;if(it.type==='heart'){boost=5;particles.push({text:'거대 짱구! BOOST ×2',life:2,x:player.x,y:player.y-130});}it.remove=true;}}}items=items.filter(i=>i.x>-100&&!i.remove);particles.forEach(p=>{p.life-=dt;p.y-=25*dt;});particles=particles.filter(p=>p.life>0);if(elapsed>=300)end(true);}
function ellipse(x,y,rx,ry,color){g.fillStyle=color;g.beginPath();g.ellipse(x,y,rx,ry,0,0,Math.PI*2);g.fill();}function rect(x,y,w,h,color){g.fillStyle=color;g.fillRect(x,y,w,h);}function text(t,x,y,size=30){g.font=`${size}px sans-serif`;g.textAlign='center';g.fillText(t,x,y);}
function shin(x,y,s){if(heroSprite.complete && heroSprite.naturalWidth){g.save();g.translate(x,y);g.scale(s,s);ellipse(0,3,26,7,'#52623b30');const bob=state==='running'?Math.sin(world/20)*2:0;g.drawImage(heroSprite,-65,-116+bob,131,120);g.restore();return;}g.save();g.translate(x,y);g.scale(s,s);const stride=state==='running'?Math.sin(world/20)*7:0;g.lineWidth=2;g.strokeStyle='#3d3029';ellipse(0,3,26,7,'#52623b30');rect(-20,-37,40,24,'#f5d24f');rect(-23,-64,46,32,'#ee5350');ellipse(-28,-46,10,8,'#ffcd9b');ellipse(28,-46,10,8,'#ffcd9b');rect(-16,-13,11,14+stride*.4,'#ffcd9b');rect(8,-13,11,14-stride*.4,'#ffcd9b');ellipse(-12-stride,1,14,7,'#f4ecbe');ellipse(16+stride,1,14,7,'#f4ecbe');ellipse(0,-86,33,28,'#ffcd9b');ellipse(24,-78,17,13,'#ffcd9b');ellipse(-30,-82,6,9,'#ffcd9b');g.fillStyle='#242321';g.beginPath();g.moveTo(-31,-92);g.quadraticCurveTo(-27,-122,7,-115);g.quadraticCurveTo(32,-115,31,-98);g.lineTo(17,-102);g.lineTo(10,-97);g.lineTo(-3,-103);g.lineTo(-15,-97);g.closePath();g.fill();g.lineWidth=6;g.beginPath();g.moveTo(-14,-95);g.lineTo(-3,-96);g.moveTo(10,-96);g.lineTo(21,-94);g.stroke();ellipse(-7,-85,2.8,4,'#252422');ellipse(16,-85,2.8,4,'#252422');g.lineWidth=2;g.beginPath();g.arc(10,-72,7,.1,2.4);g.stroke();ellipse(-18,-75,7,3,'#f5a291');g.restore();}
function draw(){const season=seasons[Math.min(3,Math.floor(elapsed/75))];rect(0,0,1200,570,season[1]);ellipse(1020,145,51,51,'#fff4b8');for(let i=0;i<6;i++){let x=((i*270-world*.13)%1500+1500)%1500-150;ellipse(x,210,140,92,season[2]);ellipse(x+110,255,160,90,season[2]);ellipse(x+40,140,44,14,'#ffffff9c');}rect(0,320,1200,250,season[3]);rect(0,367,1200,7,'#ffffff65');for(let i=0;i<8;i++){let x=((i*210-world*.5)%1650+1650)%1650-100;rect(x,250,13,105,'#a38560');ellipse(x+5,235,45,47,season[2]);if(elapsed<75){ellipse(x-15,210,28,23,'#f7d6de');ellipse(x+20,215,27,23,'#f3c9d9');}}rect(0,510,1200,60,'#b5c58c');rect(0,510,1200,5,'#829d5c');for(let i=0;i<32;i++){let x=((i*85-world)%2600+2600)%2600-50;text(season[4],x,535+(i%3)*12,15);}for(let i=0;i<14;i++){let x=(i*173+world*.15)%1200,y=110+(i*67+world*.06)%300;g.globalAlpha=.6;text(season[4],x,y,12);}g.globalAlpha=1;
if(attacker && attacker.life>0)drawAttacker(attacker);
for(const it of items){if(it.type==='rock'||it.type==='snot'||it.type==='doll')drawAttack(it);else text(({star:'⭐',candy:'🍬',cookie:'🍪',heart:'💗'})[it.type],it.x,it.y+10,38);}
if(boost>0){ellipse(player.x,player.y-player.jump-85,75,110,'#fff3a477');for(let i=0;i<4;i++)rect(player.x-130-i*25,player.y-player.jump-30-i*20,45,4,'#ffefaa');}g.globalAlpha=immune>0&&Math.floor(immune*10)%2?.4:1;shin(player.x,player.y-player.jump,boost>0?2:1);g.globalAlpha=1;for(const p of particles){g.fillStyle='#365332';g.font='bold 23px sans-serif';g.textAlign='center';g.fillText(p.text,p.x,p.y);}if(state==='paused'){rect(0,0,1200,570,'#fdf9e6aa');g.fillStyle='#345b37';text('잠깐 쉬어 가요 · 계속하기를 눌러주세요',600,285,28);}
$('time').textContent=`${String(Math.floor(Math.ceil(300-elapsed)/60)).padStart(2,'0')}:${String(Math.ceil(300-elapsed)%60).padStart(2,'0')}`;$('score').textContent=String(score).padStart(5,'0');$('speed').textContent=speedAt(elapsed).toFixed(1)+'×';$('life').textContent=lives===2?'♥ ♥':lives===1?'♥ ♡':'♡ ♡';$('season').textContent=season[0];$('boost').textContent=boost>0?`⚡ 거대 무적 부스터 ${boost.toFixed(1)}초`:immune>0?'✨ 부활! 잠시 무적 상태':'별과 간식을 모아 보세요!';$('progress').style.width=(elapsed/3)+'%';}
function frame(now){const dt=Math.min((now-last)/1000||0,1/30);last=now;if(state==='running')update(dt);draw();requestAnimationFrame(frame);}requestAnimationFrame(frame);
